import json

with open('mcp-agent-ml-research-read_registry-1778882354378.txt') as f:
    data = json.load(f)
result = json.loads(data['result'])
exps = result['data']['experiments']

# Find CLS function-level experiments (all seeds)
print('=== FUNCTION-LEVEL CLS EXPERIMENTS ===')
for eid, exp in exps.items():
    if 'cls' in eid.lower() and exp.get('status') == 'DONE':
        m = exp.get('metrics', {})
        acc = m.get('overall_accuracy', m.get('accuracy', None))
        if acc and 85 < (acc if isinstance(acc, (int, float)) else 0) < 95:
            tags = exp.get('tags', [])
            if 'repo' not in eid.lower() and 'test8192' not in eid.lower() and 'seq2048' not in eid.lower():
                print(f'{eid}: acc={acc}, tags={tags}')

print()
print('=== CWM 8B function-level ===')
for eid in ['model-size-scaling-cwm8b', 'cwm8b-seed123', 'cwm8b-seed456']:
    exp = exps.get(eid, {})
    if exp:
        m = exp.get('metrics', {})
        print(f'{eid}: acc={m.get(\"accuracy\", m.get(\"overall_accuracy\"))}, status={exp.get(\"status\")}')

print()
print('=== CLS 8B function-level ===')
for eid in ['model-size-scaling-cls8b', 'cls8b-seed123', 'cls8b-seed456']:
    exp = exps.get(eid, {})
    if exp:
        m = exp.get('metrics', {})
        print(f'{eid}: acc={m.get(\"accuracy\", m.get(\"overall_accuracy\"))}, status={exp.get(\"status\")}')

print()
print('=== ZS baselines ===')
for eid, exp in exps.items():
    if 'zero' in eid.lower() or 'zs' in eid.lower() or 'judge' in eid.lower():
        m = exp.get('metrics', {})
        print(f'{eid}: metrics={json.dumps(m)}, status={exp.get(\"status\")}')

print()
print('=== Error complementarity / oracle function-level ===')
for eid, exp in exps.items():
    m = exp.get('metrics', {})
    if isinstance(m, dict):
        mstr = json.dumps(m)
        if '90.63' in mstr or 'oracle_acc' in mstr or 'false_neg' in mstr or 'complementarity' in eid:
            print(f'{eid}: {json.dumps(m, indent=2)}')

print()
print('=== Per-test precision experiments ===')
for eid, exp in exps.items():
    m = exp.get('metrics', {})
    if isinstance(m, dict) and ('42.1' in json.dumps(m) or 'perfect_problem' in json.dumps(m)):
        print(f'{eid}: {json.dumps(m, indent=2)}')

print()
print('=== Running experiments ===')
for eid, exp in exps.items():
    if exp.get('status') == 'RUNNING':
        print(f'{eid}: status=RUNNING')
        spec = exp.get('spec', {})
        if isinstance(spec, dict):
            cmd = spec.get('command', '')
            if cmd:
                print(f'  cmd: {cmd[:120]}...')
